def car_line(cars):
    shown = [c for c in cars if c != P206T5 or P206 not in cars]  # «پژو ۲۰۶» already covers tip 5 in the sentence
    return 'مناسب برای ' + ('، '.join(shown[:-1]) + ' و ' + shown[-1] if len(shown) > 1 else shown[0]) + '.'

def first_image(i):
    for root, _, fs in os.walk(OUT):
        if '.done' in fs:
            d = json.load(open(os.path.join(root, '.done')))
            if d['id'] == i:
                return os.path.join(root, d['files'][0])
    raise KeyError(i)

def build():
    items = []
    for i, (txt, sub, name, cars, specs, extra) in sorted(ITEMS.items()):
        what, why = txt
        para1 = what + (' ' + extra if extra else '')
        desc = '\n'.join([para1, why, car_line(cars), TIP])
        sp = specs + [('خودروهای سازگار', '، '.join(cars))]
        img = first_image(i)
        assert ' - 01 ' in img, img
        items.append(dict(id=i, sku=f'AY-{1000 + i}', name=fa(name), main=MAIN, sub=sub, cars=cars,
                          description=desc, specs='\n'.join(f'{k}: {v}' for k, v in sp), images=[img], price=1000))
    data = dict(items=items, tree=TREE, cars=CARS)
    json.dump(data, open(S + '/site_import_new.json', 'w'), ensure_ascii=False, indent=1)
    return data

if __name__ == '__main__':
    d = build()
    print(len(d['items']), 'products')
    for it in d['items']:
        print(it['sku'], '|', it['sub'], '|', it['name'], '|', '، '.join(it['cars']), '|', os.path.basename(it['images'][0]))
